{"query": "mutation {
  bulkOperationRunQuery(
    query: """
    {
      orders(query: "updated_at:>='2025-01-01' AND updated_at:<'2026-01-01'") {
        edges {
          node {
            id
            name
            email
            phone
            createdAt
            updatedAt
            processedAt
            cancelledAt
            cancelReason
            displayFinancialStatus
            displayFulfillmentStatus
            test
            paymentGatewayNames
            totalPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            subtotalPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            totalTaxSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            totalShippingPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            currentTotalAdditionalFeesSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            currentTotalDutiesSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            totalTipReceivedSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            customerJourneySummary {
              ready
              customerOrderIndex
              daysToConversion
              firstVisit {
                id
                occurredAt
                landingPage
                referrerUrl
                source
                sourceDescription
                sourceType
                referralCode
                utmParameters {
                  source
                  medium
                  campaign
                  term
                  content
                }
              }
              lastVisit {
                id
                occurredAt
                landingPage
                referrerUrl
                source
                sourceDescription
                sourceType
                referralCode
                utmParameters {
                  source
                  medium
                  campaign
                  term
                  content
                }
              }
            }
            customer {
              id
              firstName
              lastName
              email
              phone
            }
            lineItems {
              edges {
                node {
                  id
                  title
                  quantity
                  currentQuantity
                  sku
                  originalUnitPriceSet {
                    shopMoney {
                      amount
                      currencyCode
                    }
                  }
                  variant {
                    id
                    title
                    sku
                    price
                  }
                  taxLines {
                    title
                    rate
                    ratePercentage
                    priceSet {
                      shopMoney {
                        amount
                        currencyCode
                      }
                    }
                    channelLiable
                    source
                  }
                  discountAllocations {
                    allocatedAmountSet {
                      shopMoney {
                        amount
                        currencyCode
                      }
                    }
                    discountApplication {
                      index
                    }
                  }
                }
              }
            }
            shippingAddress {
              firstName
              lastName
              address1
              address2
              city
              province
              country
              zip
              phone
            }
            billingAddress {
              firstName
              lastName
              address1
              address2
              city
              province
              country
              zip
              phone
            }

          }
        }
      }
    }
    """
  ) {
    bulkOperation {
      id
      status
    }
    userErrors {
      field
      message
    }
  }
}
", "variables": null, "operationName": null}

{"query": "query {
  currentBulkOperation {
    id
    status
    errorCode
    createdAt
    completedAt
    objectCount
    fileSize
    url
    partialDataUrl
  }
}
", "variables": null, "operationName": null}

